const crypto = require('crypto');
const headers = $json.headers || {};
const timestamp = String(headers['x-ghostbuster-timestamp'] || headers['X-Ghostbuster-Timestamp'] || '');
const supplied = String(headers['x-ghostbuster-signature'] || headers['X-Ghostbuster-Signature'] || '');
const rawBody = String($json.rawBody || JSON.stringify($json.body || {}));
const seconds = Number(timestamp);
const fresh = Number.isFinite(seconds) && Math.abs(Math.floor(Date.now() / 1000) - seconds) <= 300;
const expected = crypto.createHmac('sha256', $env.GHOSTBUSTER_SHARED_SECRET).update(`${timestamp}.${rawBody}`).digest('hex');
const sameLength = supplied.length === expected.length;
const valid = fresh && sameLength && crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(expected));
return [{ json: { valid, campaignId: $json.body?.campaignId || null } }];

const row = $json;
const now = new Date();
const timezone = row.timezone || row.clinic_timezone;
const start = String(row.quiet_hours_start).slice(0, 5);
const end = String(row.quiet_hours_end).slice(0, 5);
const parts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
const minute = Number(values.hour) * 60 + Number(values.minute);
const [sh, sm] = start.split(':').map(Number);
const [eh, em] = end.split(':').map(Number);
const startMinute = sh * 60 + sm;
const endMinute = eh * 60 + em;
const within = startMinute !== endMinute && (startMinute < endMinute ? minute >= startMinute && minute < endMinute : minute >= startMinute || minute < endMinute);
if (within) return [{ json: { ...row, withinWindow: true, nextAllowedAt: now.toISOString() } }];
let candidate = new Date(Math.floor(now.getTime() / 60000) * 60000 + 60000);
for (;;) {
  const candidateParts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(candidate);
  const candidateValues = Object.fromEntries(candidateParts.map((part) => [part.type, part.value]));
  const candidateMinute = Number(candidateValues.hour) * 60 + Number(candidateValues.minute);
  const allowed = startMinute !== endMinute && (startMinute < endMinute ? candidateMinute >= startMinute && candidateMinute < endMinute : candidateMinute >= startMinute || candidateMinute < endMinute);
  if (allowed) return [{ json: { ...row, withinWindow: false, nextAllowedAt: candidate.toISOString() } }];
  candidate = new Date(candidate.getTime() + 60000);
}

