const source = $('Loop Over Reserved Recipients').item.json;
const when = new Intl.DateTimeFormat('en-US', { timeZone: source.clinic_timezone, dateStyle: 'medium', timeStyle: 'short' }).format(new Date(source.appointment_time));
return [{ json: { ...source, messageBody: `${source.clinic_name}: an opening is available ${when}. Reply YES to claim it. Reply STOP to opt out.` } }];

const crypto = require('crypto');
const headers = $json.headers || {};
const supplied = String(headers['x-twilio-signature'] || headers['X-Twilio-Signature'] || '');
const body = $json.body || {};
const url = $vars.TWILIO_INBOUND_WEBHOOK_URL;
const payload = Object.keys(body).sort().reduce((value, key) => `${value}${key}${body[key]}`, url);
const expected = crypto.createHmac('sha1', $env.TWILIO_AUTH_TOKEN).update(payload).digest('base64');
const valid = supplied.length === expected.length && crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(expected));
return [{ json: { valid, messageSid: body.MessageSid || body.SmsSid, from: body.From, body: body.Body || '' } }];

const text = String($json.body || '').trim();
const keyword = text.toUpperCase().replace(/[.!?,;:]+$/g, '').trim();
const sets = {
  OPT_OUT: ['STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT'],
  OPT_IN: ['START','UNSTOP'],
  HELP: ['HELP','INFO'],
  AFFIRMATIVE: ['YES','Y','YEP','YEAH','CLAIM','1'],
};
let classification = 'OTHER';
for (const [name, values] of Object.entries(sets)) if (values.includes(keyword)) classification = name;
const phone = String($json.from || '').trim();
return [{ json: { ...$json, phone, phoneValid: /^\+[1-9]\d{7,14}$/.test(phone), classification, normalizedBody: keyword } }];

const patient = $('Resolve Patient').first().json;
const inbound = $('Normalize Phone and Classify Keyword').first().json;
return [{ json: { patientId: patient.id, campaignId: null, to: inbound.phone, messageBody: "Reply YES to claim an active opening. Reply STOP to opt out. Call the clinic for other help." } }];

